//! "Wayside Cross in the Snow at Evening" — an original winter picture in the
//! manner of Caspar David Friedrich (written from notes/research, never from
//! images).
//!
//! A snow-covered rise fills the foreground; on its crest, on the picture's
//! central axis, stands a weathered wooden cross between two young spruces.
//! Below it, with his back to us, a traveler in a cape leans on his stick
//! and looks up. On the left a dead oak with broken limbs, crows in it. Beyond
//! the rise the land drops away into evening fog: rows of spruces rise out of
//! it, and far off the ghost of a church tower. The sky after sunset: grey
//! blue above, mauve, then a pale lemon glow over the fog.
//!
//! Order of work (CATS p.127, NG p.56): bought ground, graphite underdrawing,
//! a very thin underpainting, sky, distance to foreground, figures last, then
//! the grasses over the finished snow and the finish.

use paint::color::{Mix, gradient, mix};
use paint::{Canvas, Fbm, Gesture, Handling, Held, Mask, Oak, Orient, Paint, Rgb, Rng, Shape, Style, Tool, hex, smoothstep};
use paintings::run::{Finish, Run};
use paintings::{figures, trees};

const ASPECT: f32 = 1.45;
/// Far edge of the snow plain, lost in the fog.
const HORIZON: f32 = 455.0;
/// The cross stands on the central axis.
const AXIS: f32 = 500.0;

/// The crest of the foreground rise (y in units for x).
fn crest(x: f32) -> f32 {
    600.0 - 96.0 * (-((x - AXIS) / 330.0).powi(2)).exp() - 5.0 * (x * 0.013 + 1.0).sin() - 2.5 * (x * 0.047).sin()
}

fn crest_slope(x: f32) -> f32 {
    (crest(x + 1.0) - crest(x - 1.0)) * 0.5
}

/// The evening sky: grey blue at the top, mauve, then a pale lemon glow over
/// the fog, strongest a little right of center where the sun went down.
fn sky(x: f32, y: f32) -> Rgb {
    let t = (y / HORIZON).clamp(0.0, 1.0);
    let base = gradient(
        &[(0.0, hex("#6c7890")), (0.3, hex("#8e93aa")), (0.55, hex("#b7a9b2")), (0.75, hex("#d8c4b2")), (0.9, hex("#e7d6b6")), (1.0, hex("#ecdfc0"))],
        t,
        Mix::Light,
    );
    let g = (-((x - 610.0) / 280.0).powi(2)).exp() * smoothstep(0.5, 1.0, t);
    mix(base, hex("#f1dfae"), g * 0.55, Mix::Light)
}

/// Fog color: the sky's light, a little greyer.
fn fog(x: f32, y: f32) -> Rgb {
    mix(sky(x, HORIZON), hex("#cfc8c0"), 0.35 + 0.25 * smoothstep(HORIZON - 40.0, HORIZON + 60.0, y), Mix::Light)
}

/// One brush, loaded once, one gesture.
#[allow(clippy::too_many_arguments)]
fn stroke(c: &mut Canvas, tool: Tool, paint: Paint, load: f32, pts: Vec<(f32, f32)>, p: (f32, f32), ramps: (f32, f32), seed: u64) {
    let mut h = Held::new(tool, seed);
    h.load(paint, load);
    c.drag(&mut h, &Gesture::new(pts).pressure(p.0, p.1).ramps(ramps.0, ramps.1).orient(Orient::Across), None);
}

/// A stipple: many tiny dabs of a small round brush, the way Friedrich laid
/// skies and mist (NG p.56).
fn stipple<'a>(st: &'a Style, width: f32, medium: f32, coverage: f32) -> Handling<'a> {
    Handling::new(Tool { ragged: 0.4, ..Tool::round_sable(width) })
        .length(0.4, 1.6)
        .coverage(coverage)
        .mixed(&st.palette, medium)
        .mix_jitter(0.05)
        .pressure(0.35, 0.65)
        .dips(4, 0.25, 0.3)
        .ramps(0.3, 0.5)
        .angle_jitter(3.0)
        .threshold(0.2)
}

fn main() {
    let run = Run::new("fresh_winter");
    let st = Style::friedrich();
    let pal = &st.palette;
    let mut c = st.prepare(run.width, ASPECT, run.seed);
    let f = c.frame();
    let h = c.height();
    if run.stage(&mut c, "ground") {
        return;
    }

    // ---- underdrawing: graphite lines, ruled where the thing is ruled
    let graphite = pal.paint(hex("#555049"), 0.55);
    let pencil = Tool { width: 0.9, length: 4.0, ..Tool::rigger(0.9) };
    let crest_line: Vec<(f32, f32)> = (0..=40).map(|i| (i as f32 * 25.0, crest(i as f32 * 25.0))).collect();
    stroke(&mut c, pencil.clone(), graphite, 0.25, crest_line, (0.45, 0.4), (0.05, 0.05), 1);
    stroke(&mut c, pencil.clone(), graphite, 0.2, vec![(0.0, HORIZON), (1000.0, HORIZON + 2.0)], (0.35, 0.35), (0.05, 0.05), 2);
    // the cross, ruled
    let cross_base = (AXIS + 2.0, crest(AXIS) + 4.0);
    let cross_top = (AXIS - 3.0, 318.0);
    stroke(&mut c, pencil.clone(), graphite, 0.25, vec![cross_base, cross_top], (0.5, 0.5), (0.02, 0.02), 3);
    stroke(&mut c, pencil.clone(), graphite, 0.25, vec![(AXIS - 38.0, 352.0), (AXIS + 36.0, 351.0)], (0.5, 0.5), (0.02, 0.02), 4);
    // oak axis, figure, spruce axes
    stroke(&mut c, pencil.clone(), graphite, 0.2, vec![(190.0, crest(190.0)), (182.0, 420.0), (200.0, 300.0)], (0.4, 0.3), (0.05, 0.1), 5);
    stroke(&mut c, pencil.clone(), graphite, 0.2, vec![(462.0, 612.0), (466.0, 668.0)], (0.4, 0.4), (0.05, 0.1), 6);
    c.dry();
    if run.stage(&mut c, "drawing") {
        return;
    }

    // ---- underpainting: a very thin violet layer in the sky (as in the
    // sky of The Cross in the Mountains, KÖR fig. 6), thin warm grey on the land
    let sky_m = Mask::from_fn(f, |_, y| 1.0 - smoothstep(HORIZON + 30.0, HORIZON + 60.0, y));
    let under_sky = st.broad().color(|_, y| mix(hex("#8a7f95"), hex("#b59c9a"), y / HORIZON, Mix::Light)).medium(0.8).dips(2, 0.25, 0.5).coverage(1.8);
    c.work(&sky_m, &under_sky, 11);
    let land_m = Mask::from_fn(f, |_, y| smoothstep(HORIZON + 10.0, HORIZON + 40.0, y));
    let under_land = st.broad().color(|_, _| hex("#9c948c")).medium(0.8).dips(2, 0.25, 0.5).coverage(1.8);
    c.work(&land_m, &under_land, 12);
    c.dry();
    if run.stage(&mut c, "under") {
        return;
    }

    // ---- sky: long horizontal strokes, fused with the badger, then a stipple
    let sky_paint = st.broad().color(sky).angle(|_, _| 0.0).coverage(3.0);
    c.work(&sky_m, &sky_paint, 21);
    if let Some(b) = st.blend() {
        for k in 0..st.blend_passes {
            c.work(&sky_m, &b, 22 + k as u64);
        }
    }
    c.dry();
    let lift = |x: f32, y: f32| mix(sky(x, y), hex("#f2ead8"), 0.12, Mix::Light);
    let st_sky = stipple(&st, 3.5, 0.55, 1.6).color(lift);
    c.work(&sky_m, &st_sky, 23);
    c.dry();
    if run.stage(&mut c, "sky") {
        return;
    }

    // ---- distance: faint far hills, the snow plain, the fog
    let hills = |x: f32| HORIZON - 18.0 - 14.0 * (x * 0.006 + 0.7).sin() - 6.0 * (x * 0.021).sin();
    let hill_m = Mask::from_fn(f, |x, y| smoothstep(hills(x) - 1.5, hills(x) + 1.5, y) * (1.0 - smoothstep(HORIZON + 10.0, HORIZON + 30.0, y)));
    let hill_paint = st.body().color(|x, y| mix(fog(x, y), hex("#8f8ea0"), 0.45, Mix::Light)).medium(0.5).angle(|_, _| 0.0).length(30.0, 70.0);
    c.work(&hill_m, &hill_paint, 31);
    let plain_m = Mask::from_fn(f, |x, y| smoothstep(HORIZON - 2.0, HORIZON + 2.0, y) * (1.0 - smoothstep(crest(x) + 30.0, crest(x) + 50.0, y)));
    let plain = st.broad().color(|x, y| mix(fog(x, y), hex("#b9b8c2"), smoothstep(HORIZON, 560.0, y) * 0.6, Mix::Light)).medium(0.35).angle(|_, _| 0.0);
    c.work(&plain_m, &plain, 32);
    if let Some(b) = st.blend() {
        c.work(&plain_m, &b, 33);
    }
    c.dry();

    // the church tower far off in the fog
    let tx = 655.0;
    let tower = Shape::new()
        .poly(&[(tx - 4.0, HORIZON + 2.0), (tx - 4.0, 395.0), (tx - 5.0, 393.0), (tx, 362.0), (tx + 5.0, 393.0), (tx + 4.0, 395.0), (tx + 4.0, HORIZON + 2.0)])
        .poly(&[(tx + 4.0, HORIZON + 2.0), (tx + 4.0, 425.0), (tx + 14.0, 415.0), (tx + 34.0, 415.0), (tx + 38.0, 425.0), (tx + 38.0, HORIZON + 2.0)]);
    let tower_m = Mask::from_shape(f, tower);
    let tower_paint = st.detail().color(|x, y| mix(fog(x, y), hex("#8c8a98"), 0.4, Mix::Light)).medium(0.35).angle(|_, _| -1.5707);
    c.work(&tower_m, &tower_paint, 34);
    c.dry();

    // far rows of spruces rising out of the fog, back to front, the fog
    // laid over the feet of each row
    let mut rng = Rng::new(40);
    let groups = [(20.0f32, 300.0f32, 0.8f32), (700.0, 990.0, 1.0)];
    for row in 0..3 {
        let depth = row as f32 / 2.0; // 0 far .. 1 near
        let base_y = HORIZON + 6.0 + depth * 30.0;
        let target = mix(fog(500.0, base_y), hex("#3f4442"), 0.35 + 0.5 * depth, Mix::Light);
        let col = pal.mix(target).color;
        for &(x0, x1, dens) in &groups {
            let n = ((x1 - x0) / (26.0 - depth * 6.0) * dens) as usize;
            for _ in 0..n {
                let x = rng.range(x0, x1);
                // the copse is highest in its middle
                let mid = (x - x0) / (x1 - x0);
                let hump = (1.0 - (2.0 * mid - 1.0).powi(2)).max(0.0);
                let ht = (30.0 + 60.0 * depth) * (0.5 + 0.7 * hump) * rng.range(0.7, 1.15);
                trees::spruce(&mut c, (x, base_y + rng.range(-3.0, 3.0)), ht, col, rng.next_u64());
            }
        }
        c.dry();
        let fog_m = Mask::from_fn(f, |_, y| smoothstep(HORIZON - 70.0, HORIZON - 30.0, y) * (1.0 - smoothstep(base_y + 30.0, base_y + 60.0, y)));
        let fog_paint = st
            .glaze(0.6)
            .color(fog)
            .angle(|_, _| 0.0)
            .load_at(move |_, y| 0.25 + 0.75 * smoothstep(HORIZON - 60.0, base_y, y));
        c.work(&fog_m, &fog_paint, 41 + row as u64);
        if let Some(b) = st.blend() {
            c.work(&fog_m, &b, 44 + row as u64);
        }
        c.dry();
    }
    if run.stage(&mut c, "distance") {
        return;
    }

    // ---- the foreground rise: snow in shadow (the light is behind the
    // fog), cool lavender grey, drifts, a warm lit edge along the crest
    let drift = Fbm::new(7, 4, 140.0);
    let snow_col = move |x: f32, y: f32| {
        let d = (y - crest(x)).max(0.0);
        let lit = 1.0 - smoothstep(0.0, 22.0, d);
        let n = drift.get(x, y * 2.2);
        let shade = gradient(&[(0.0, hex("#c7c3c6")), (0.5, hex("#b4b3bd")), (1.0, hex("#a2a3b1"))], smoothstep(0.0, 180.0, d) * 0.7 + 0.3 * (0.5 - 0.5 * n), Mix::Light);
        mix(shade, hex("#e9dfcd"), lit * 0.8, Mix::Light)
    };
    let fg_m = Mask::from_fn(f, |x, y| smoothstep(crest(x) - 1.0, crest(x) + 1.0, y));
    let snow = st.body().color(snow_col).angle(|x, y| {
        let d = (y - crest(x)).max(0.0);
        (crest_slope(x) * (1.0 - smoothstep(0.0, 150.0, d))).atan()
    }).length(30.0, 80.0).medium(0.25);
    c.work(&fg_m, &snow, 51);
    if let Some(b) = st.blend() {
        c.work(&fg_m, &b.pressure(0.3, 0.4), 52);
    }
    c.dry();
    // slight impasto of the foreground snow (NG p.50): lead white laid
    // stiffly along the crest and on the tops of the drifts
    let top = Fbm::new(9, 3, 90.0);
    let lit_m = Mask::from_fn(f, move |x, y| {
        let d = y - crest(x);
        smoothstep(-1.0, 1.0, d) * ((1.0 - smoothstep(4.0, 16.0, d)) + 0.5 * smoothstep(0.35, 0.6, top.get(x, y * 2.5)) * smoothstep(40.0, 80.0, d))
    });
    let white = st.body().color(|x, _| mix(hex("#ece4d4"), hex("#f0e2c4"), (-((x - 610.0) / 250.0).powi(2)).exp(), Mix::Light)).medium(0.1).length(15.0, 40.0).coverage(1.5).angle(|x, _| crest_slope(x).atan());
    c.work(&lit_m, &white, 53);
    c.dry();
    if run.stage(&mut c, "snow") {
        return;
    }

    // ---- the dead oak on the left
    let mut oak = Oak::new((190.0, crest(190.0) + 6.0), 400.0, 17);
    oak.gnarl = 0.85;
    oak.broken = 0.32;
    oak.lean = -0.05;
    oak.depth = 5;
    oak.roots = 3;
    let bark = pal.mix(hex("#2b2522")).color;
    let bark_light = pal.mix(hex("#8e8472")).color;
    oak.paint(&mut c, bark, Some(bark_light), 18);
    c.dry();
    // snow lying along the tops of the heavier limbs
    let snow_paint = pal.paint(hex("#e6e0d6"), 0.15);
    let mut r = Rng::new(19);
    for l in oak.grow().iter().filter(|l| l.w[0] > 1.6 && l.depth <= 3) {
        for s in l.pts.windows(2).zip(l.w.windows(2)) {
            let ((a, b), (wa, wb)) = ((s.0[0], s.0[1]), (s.1[0], s.1[1]));
            let (dx, dy) = (b.0 - a.0, b.1 - a.1);
            let len = (dx * dx + dy * dy).sqrt().max(1e-3);
            // only limbs that lie more across than up hold snow
            let flat = (dx.abs() / len - 0.35).max(0.0) / 0.65;
            if flat <= 0.05 || r.chance(0.3) {
                continue;
            }
            let (nx, ny) = (-dy / len, dx / len);
            let (nx, ny) = if ny < 0.0 { (nx, ny) } else { (-nx, -ny) };
            let off = |p: (f32, f32), w: f32| (p.0 + nx * w * 0.42, p.1 + ny * w * 0.42);
            let w = (wa.min(wb) * 0.45).max(0.8);
            stroke(&mut c, Tool::round_sable(w), snow_paint, 0.5, vec![off(a, wa), off(b, wb)], (0.7 * flat + 0.2, 0.5 * flat + 0.1), (0.2, 0.4), r.next_u64());
        }
    }
    c.dry();

    // ---- the cross between two young spruces
    let wood = pal.paint(hex("#2e2722"), 0.1);
    let wood_tool = |w: f32| Tool { ragged: 0.3, ..Tool::round_sable(w) };
    stroke(&mut c, wood_tool(6.5), wood, 1.0, vec![cross_base, (AXIS - 0.5, 420.0), cross_top], (0.95, 0.9), (0.0, 0.05), 61);
    stroke(&mut c, wood_tool(5.5), wood, 1.0, vec![(AXIS - 38.0, 352.0), (AXIS + 36.0, 351.0)], (0.9, 0.9), (0.0, 0.03), 62);
    // a small gabled roof over the cross, as on wayside crosses
    stroke(&mut c, wood_tool(3.0), wood, 0.8, vec![(AXIS - 16.0, 330.0), (AXIS - 3.0, 317.0), (AXIS + 11.0, 330.0)], (0.9, 0.9), (0.0, 0.05), 63);
    c.dry();
    let snow_top = pal.paint(hex("#ede5d6"), 0.1);
    stroke(&mut c, Tool::round_sable(2.2), snow_top, 0.6, vec![(AXIS - 37.0, 348.8), (AXIS + 35.0, 347.8)], (0.7, 0.6), (0.1, 0.2), 64);
    stroke(&mut c, Tool::round_sable(2.0), snow_top, 0.6, vec![(AXIS - 15.0, 327.0), (AXIS - 3.0, 315.5), (AXIS + 10.0, 327.0)], (0.7, 0.6), (0.1, 0.2), 65);
    let spruce_col = pal.mix(hex("#1f2622")).color;
    trees::spruce(&mut c, (AXIS - 52.0, crest(AXIS - 52.0) + 4.0), 95.0, spruce_col, 66);
    trees::spruce(&mut c, (AXIS + 55.0, crest(AXIS + 55.0) + 4.0), 118.0, spruce_col, 67);
    c.dry();
    if run.stage(&mut c, "motifs") {
        return;
    }

    // ---- figures last: the traveler, and the crows
    let cape = pal.mix(hex("#34382f")).color;
    let dark = pal.mix(hex("#15130f")).color;
    let hair = pal.mix(hex("#2a2119")).color;
    let rim = pal.mix(hex("#b8a78c")).color;
    figures::man_in_cape(&mut c, (466.0, 668.0), 62.0, cape, dark, hair, Some(rim), 71);
    let crow = pal.paint(hex("#191715"), 0.1);
    let mut r = Rng::new(72);
    for &(x, y, s) in &[(118.0f32, 262.0f32, 1.0f32), (262.0, 300.0, 0.9), (206.0, 228.0, 0.8), (330.0, 150.0, 1.1), (372.0, 172.0, 0.95)] {
        let fly = y < 200.0;
        let t = Tool::round_sable(2.2 * s);
        if fly {
            stroke(&mut c, t.clone(), crow, 0.8, vec![(x - 7.0 * s, y - 2.5 * s), (x - 3.0 * s, y - 0.5 * s), (x, y + 0.5)], (0.3, 0.9), (0.1, 0.1), r.next_u64());
            stroke(&mut c, t, crow, 0.8, vec![(x, y + 0.5), (x + 3.5 * s, y - 1.5 * s), (x + 7.5 * s, y - 3.0 * s)], (0.9, 0.3), (0.1, 0.1), r.next_u64());
        } else {
            // perched: body, head, a flick of tail
            stroke(&mut c, t.clone(), crow, 0.9, vec![(x, y - 4.0 * s), (x + 0.8, y + 1.0)], (1.0, 0.9), (0.0, 0.2), r.next_u64());
            stroke(&mut c, Tool::round_sable(1.4 * s), crow, 0.9, vec![(x + 0.8, y + 1.0), (x + 2.0, y + 4.5 * s)], (0.9, 0.3), (0.0, 0.4), r.next_u64());
        }
    }
    c.dry();
    if run.stage(&mut c, "figures") {
        return;
    }

    // ---- grass over the finished snow with fine upturning strokes (NG p.56)
    let grass = [pal.paint(hex("#6e5a40"), 0.2), pal.paint(hex("#4a3d2e"), 0.2), pal.paint(hex("#8a7453"), 0.2)];
    let mut r = Rng::new(81);
    let tufts: Vec<(f32, f32, f32)> = (0..70)
        .map(|_| {
            let x = r.range(0.0, 1000.0);
            // along the crest, and in the near foreground
            let y = if r.chance(0.4) { crest(x) + r.range(2.0, 10.0) } else { r.range(crest(x) + 60.0, h) };
            (x, y, r.range(0.6, 1.4))
        })
        .filter(|&(x, y, _)| (x - 466.0).abs() > 30.0 || y < 600.0)
        .collect();
    for (x, y, s) in tufts {
        let k = 3 + (s * 4.0) as usize;
        let near = smoothstep(500.0, h, y);
        for _ in 0..k {
            let len = (6.0 + 16.0 * near) * s * r.range(0.6, 1.2);
            let lean = r.normal() * 0.35;
            let x0 = x + r.normal() * 3.0 * s;
            let pts = vec![(x0, y), (x0 + lean * len * 0.4, y - len * 0.55), (x0 + lean * len, y - len)];
            let g = grass[r.next_u64() as usize % 3];
            stroke(&mut c, Tool { width: 0.5 + 0.6 * near, ..Tool::rigger(0.5 + 0.6 * near) }, g, 0.6, pts, (0.8, 0.1), (0.0, 0.6), r.next_u64());
        }
    }
    c.dry();
    if run.stage(&mut c, "grass") {
        return;
    }

    // ---- a last thin glaze, deeper toward the edges and the bottom
    let all = Mask::full(f);
    let edge = st
        .glaze(0.92)
        .color(|_, _| hex("#5a4c44"))
        .load_at(move |x, y| {
            let dx = (x - 540.0) / 560.0;
            let dy = (y - 380.0) / (h * 0.6);
            smoothstep(0.55, 1.25, (dx * dx + dy * dy).sqrt()) * 0.9
        })
        .threshold(0.0);
    c.work(&all, &edge, 91);
    if let Some(b) = st.blend() {
        c.work(&all, &b, 92);
    }
    run.finish(&mut c, &Finish::aged(st.relief));
}

