/// fused with the badger before the next is started; then left to dry.
fn sky_layer(c: &mut Canvas, st: &Style, col: &(dyn Fn(f32, f32) -> Rgb + Sync), medium: f32, bottom: f32, seed: u64) {
    let f = c.frame();
